    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            left = any(grid[r][x] != bg for r in range(h) for x in range(c))
            right = any(grid[r][x] != bg for r in range(h) for x in range(c+1,w))
            if right and not left:
                cols=[x for r in range(h) for x in range(c+1,w) if grid[r][x] != bg]
                x=max(cols)+1
            elif left and not right:
                cols=[x for r in range(h) for x in range(c) if grid[r][x] != bg]
                x=min(cols)-1
            else:
                continue
            if 0 <= x < w and all(grid[r][x] == bg for r in range(h)):
                for r in range(h): out[r][x]=8
            break
    return out
